                ans = 0;
            } else {
                ans = mul(ans, m / pre);
            }
            ans1 = mul(ans1, M);
            res = mod(res + ans1 - ans);
        }
        return res;
    }

    static int[] getPrimes(int n) {
        int[] nums = new int[n + 1];
        Arrays.fill(nums, 1);
        nums[0] = 0;
        nums[1] = 0;
        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= n; i++) {
            if (nums[i] == 1) primes.add(i);
            for (int j = 0; j < primes.size() && primes.get(j) <= n / i; j++) {
                int pj = primes.get(j);
                nums[pj * i] = 0;
                if (i % pj == 0) break;
            }
        }
        return nums;
    }

    static long mod(long num) {
        if (num >= MOD) return num % MOD;
        else if (num < 0) return (num % MOD + MOD) % MOD;
        return num;
    }

