            System.arraycopy(args, 2, rest, 0, args.length - 2);
            return mul(mul(a, b), rest);
        }
        long high = (a / 65536L) * b % MOD * 65536L;
        long low = (a & 65535L) * b;
        return (high + low) % MOD;
    }

