            String s = read.get();
            if (s == null || s.isEmpty()) return new long[0];
            String[] parts = s.trim().split("\\s+");
            long[] arr = new long[parts.length];
            for (int i = 0; i < parts.length; i++) arr[i] = Long.parseLong(parts[i]);
            return arr;
        };

        return ic;
    }
